import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { HashRouter } from 'react-router';
import { toast } from 'sonner';
import { beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import App from './app';
import type {
  ChangeDetail,
  ChangeList,
  ModelInfo,
  RecordEnvelope,
  WorkspaceRecord,
} from './types/dto';
import type { CodeStatsReport, WorkspaceConfigReport } from './types/generated/bindings';

const { checkMock, getVersionMock, invokeMock, openMock } = vi.hoisted(() => ({
  checkMock: vi.fn(),
  getVersionMock: vi.fn(),
  invokeMock: vi.fn(),
  openMock: vi.fn(),
}));

vi.mock('@tauri-apps/api/app', () => ({ getVersion: getVersionMock }));
vi.mock('@tauri-apps/api/core', () => ({ invoke: invokeMock }));
vi.mock('@tauri-apps/plugin-dialog', () => ({ open: openMock }));
// updater mock（沿用 use-updater.test.ts 语义）：启动检查判据为 `mode === 'prod'`
// （IPC `app_environment` 单源）——默认 dev fixture 跳过启动检查，需检查路径的
// 用例经 `environmentMode = 'prod'` 切换
vi.mock('@tauri-apps/plugin-updater', () => ({ check: checkMock }));
// 保留 HashRouter 实现、仅观测 props：锁定「路由更新同步提交」修复点
vi.mock(import('react-router'), async (importOriginal) => {
  const actual = await importOriginal();
  return { ...actual, HashRouter: vi.fn(actual.HashRouter) };
});

// ---------------------------------------------------------------------------
// fixture：workspace 清单为默认序（canonical root 升序），FIRST 即默认序第一名
// ---------------------------------------------------------------------------

const FIRST: WorkspaceRecord = {
  root: 'C:\\demo\\alpha',
  name: 'alpha',
  addedAt: 1,
};
const SECOND: WorkspaceRecord = {
  root: 'C:\\demo\\beta',
  name: 'beta',
  addedAt: 1,
};

/** change 身份锚（uuid 形态）——URL 段 / 取数键恒该值，'add-feature' 恒展示面。 */
const CHANGE_ID = '0199a2f0-3001-7e45-8a9b-000000003001';

const fakeList: ChangeList = {
  active: [
    {
      id: CHANGE_ID,
      name: 'add-feature',
      title: 'add-feature',
      source: 'active',
      status: 'active',
      activePhase: null,
      created: null,
    },
  ],
  archiveGroups: [],
};

const fakeDetail: ChangeDetail = {
  id: CHANGE_ID,
  name: 'add-feature',
  title: 'add-feature',
  source: 'active',
  status: 'active',
  created: null,
  pipeline: [],
  activePhase: null,
  runs: [],
  artifacts: [],
  worktree: null,
};

// db 查看域 fixture：DbInspectorView 挂载即 invoke("db_models")，mock 必须回
// 数组形态（null 会使 hook state.models 置 null 而崩）；db_records 回分页信封
// （records 按 offset/limit 切页 + total = 库存全量计数）
const DB_MODELS: ModelInfo[] = [
  { name: 'workspace', count: 2 },
  { name: 'agent_run', count: 1 },
  { name: 'agent_event', count: 0 },
];
const DB_RECORDS: RecordEnvelope[] = [
  { key: 'C:\\demo\\alpha', value: { root: 'C:\\demo\\alpha', name: 'alpha', addedAt: 1 } },
  { key: 1, value: { id: 1, prompt: '你好', status: 'completed' } },
  { key: { runId: 1, seq: 0 }, value: { eventKey: '0x1', runId: 1, event: { seq: 0 } } },
];

// 基础信息域 fixture：InfoView 挂载即以 (root, depth=5) invoke("code_stats")，
// 三面 DTO（totals.files > 0 → 非空态），树面顶层节点默认展开在 DOM
const CODE_STATS: CodeStatsReport = {
  totals: { files: 12, code: 340, comments: 40, blanks: 20 },
  languages: [
    { name: 'Rust', files: 6, code: 220, comments: 30, blanks: 10, share: 64.7 },
    { name: 'TypeScript', files: 6, code: 120, comments: 10, blanks: 10, share: 35.3 },
  ],
  tree: [
    {
      kind: 'dir',
      node: {
        name: 'src',
        path: 'src',
        files: 9,
        code: 300,
        comments: 35,
        blanks: 18,
        children: [],
      },
    },
  ],
};

// 配置域 fixture：ConfigView 挂载即 invoke("workspace_config")，camelCase 信封
// （config + diagnostics）；context 归属 root 由 configReportFor 注入（切换
// 用例区分新旧根数据）
const WORKSPACE_CONFIG: WorkspaceConfigReport = {
  config: {
    $schema: null,
    schema: 'spec-driven',
    context: null,
    rules: { proposal: ['提案规则'], tasks: null },
    staticAnalysis: 'clippy',
    tests: [
      {
        root: 'packages/desktop',
        framework: 'vite-plus',
        cwd: 'packages/desktop',
        config: null,
        includes: null,
        excludes: null,
        coverage: { lines: 80, branches: 70, functions: 75 },
        mutation: { cwd: null, score: 70 },
      },
    ],
    writeProtection: null,
    extra: [],
  },
  diagnostics: [
    {
      kind: 'defaultApplied',
      path: 'tests[0].coverage.lines',
      message: '覆盖率阈值 lines 未设置，使用默认值 80。',
    },
  ],
};

/** 配置报告 fixture 深拷贝（防用例间引用残留），context 承载归属 root。 */
function configReportFor(root: string): WorkspaceConfigReport {
  const report = JSON.parse(JSON.stringify(WORKSPACE_CONFIG)) as WorkspaceConfigReport;
  report.config.context = root;
  return report;
}

// ---------------------------------------------------------------------------
// 进程边界 Mock：IPC 按命令名分发；文件夹对话框按用例 resolve / reject / cancel；
// 版本号固定 resolve。sonner <Toaster /> 不 mock：App 根真实挂载，toast 断言走
// DOM 文案 + waitFor。sonner toast 状态为模块级单例、跨用例存活，beforeEach
// 统一 dismiss 防残留。
// ---------------------------------------------------------------------------

let remaining: WorkspaceRecord[];
let addBehavior: 'ok' | 'reject' = 'ok';
let addRecord: WorkspaceRecord | null = null;
let listReject: string | null = null;
let configReject: string | null = null;
let configPending = false;
/// 架构页取数失败注入位（`archi_graph` reject 形态）
let archiReject: string | null = null;

/** 架构图 fixture（两元素零关系零诊断；`archi_graph` / `archi_module` 共用）。 */
const ARCHI_ELEMENTS = [
  {
    fqn: 'App',
    kind: 'package' as const,
    gate: 'off' as const,
    path: [],
    summary: null,
    metadata: {},
    modelFile: 'openspec/architecture/models/01-core.toml',
    modelLine: 2,
    mark: 'none' as const,
  },
  {
    fqn: 'App.Auth',
    kind: 'domain' as const,
    gate: 'strict' as const,
    path: ['./src/auth/'],
    summary: '认证域',
    metadata: {},
    modelFile: 'openspec/architecture/models/01-core.toml',
    modelLine: 6,
    mark: 'none' as const,
  },
];

// 构建模式单源（IPC `app_environment`）：默认 dev fixture（徽标在场、更新检查
// 不发起）；需检查路径的用例切 'prod'；另备 reject / pending / null / 非法载荷
// 四档表达「未就绪 / 取数失败 / 载荷不合法」。
const DEV_DATA_ROOT = 'C:\\u\\.dev-team\\dev';
const PROD_DATA_ROOT = 'C:\\u\\.dev-team';
const DEV_ENVIRONMENT = { mode: 'dev', dataRoot: DEV_DATA_ROOT, source: 'dev-default' };
const PROD_ENVIRONMENT = { mode: 'prod', dataRoot: PROD_DATA_ROOT, source: 'prod' };
let environmentMode: 'dev' | 'prod' | 'reject' | 'pending' | 'null' | 'invalid' = 'dev';

function mockIpc() {
  remaining = [FIRST, SECOND];
  addBehavior = 'ok';
  addRecord = null;
  listReject = null;
  configReject = null;
  configPending = false;
  archiReject = null;
  environmentMode = 'dev';
  invokeMock.mockImplementation(
    (command: string, params?: { root?: string; id?: string; offset?: number; limit?: number }) => {
      // 构建模式单源（壳层挂载一次）：dev / prod fixture 与 reject / pending /
      // null / 非法载荷四档（后四档落入「mode 未知」路径）
      if (command === 'app_environment') {
        if (environmentMode === 'reject') return Promise.reject(new Error('IPC 不可用'));
        if (environmentMode === 'pending') return new Promise<unknown>(() => {});
        if (environmentMode === 'null') return Promise.resolve(null);
        if (environmentMode === 'invalid') {
          return Promise.resolve({ mode: 'other', dataRoot: 5 });
        }
        return Promise.resolve(
          environmentMode === 'prod' ? { ...PROD_ENVIRONMENT } : { ...DEV_ENVIRONMENT },
        );
      }
      if (command === 'list_workspaces') {
        if (listReject !== null) return Promise.reject(new Error(listReject));
        return Promise.resolve([...remaining]);
      }
      // 移除面（选择器 UI 已不含移除入口——保留命令桩：导航 / 欢迎态用例的
      // 「零 remove 命令」负断言仍在场）
      if (command === 'remove_workspace') {
        remaining = remaining.filter((r) => r.root !== params?.root);
        return Promise.resolve(true);
      }
      if (command === 'add_workspace') {
        if (addBehavior === 'reject') {
          return Promise.reject(new Error('canonicalize: 入库失败'));
        }
        const rec: WorkspaceRecord = addRecord ?? {
          root: params?.root ?? '',
          name: 'picked',
          addedAt: 1,
        };
        // 对齐后端：库存按默认序（canonical root 升序）返回，新记录未必居首
        remaining = [...remaining.filter((r) => r.root !== rec.root), rec].sort((a, b) =>
          a.root < b.root ? -1 : a.root > b.root ? 1 : 0,
        );
        return Promise.resolve(rec);
      }
      if (command === 'list_changes') {
        return Promise.resolve(fakeList);
      }
      if (command === 'get_change_detail') {
        // 统一视图信封（detail ∪ activeRun——unify-run-state-persistence 线面）
        return Promise.resolve({ detail: fakeDetail, activeRun: null });
      }
      if (command === 'db_models') {
        return Promise.resolve(DB_MODELS.map((model) => ({ ...model })));
      }
      if (command === 'db_records') {
        const offset = params?.offset ?? 0;
        const limit = params?.limit ?? 50;
        const records = DB_RECORDS.slice(offset, offset + limit).map((e) => ({ ...e }));
        return Promise.resolve({ records, total: DB_RECORDS.length });
      }
      if (command === 'agent_sessions') {
        return Promise.resolve({ sessions: [], total: 0 });
      }
      if (command === 'agent_session_transcript') {
        return Promise.resolve([]);
      }
      // agent 选择器挂载取数（useAgentOptions 发起 list_agent_instances）：同回
      // 数组形态（null 会使实例清单置 null 而崩），页面切页断言不涉及其内容
      if (command === 'list_agent_instances') {
        return Promise.resolve([]);
      }
      // 基础信息页挂载取数（useCodeStats 挂载发起 code_stats）：回三面 DTO，
      // fixture 深拷贝防用例间引用残留
      if (command === 'code_stats') {
        return Promise.resolve(JSON.parse(JSON.stringify(CODE_STATS)) as CodeStatsReport);
      }
      // 配置页挂载取数（useWorkspaceConfig 挂载发起 workspace_config）：
      // resolve（context 归属 root）/ reject / 手动 pending 三态控制
      if (command === 'workspace_config') {
        if (configReject !== null) return Promise.reject(new Error(configReject));
        if (configPending) return new Promise<WorkspaceConfigReport>(() => {});
        return Promise.resolve(configReportFor(params?.root ?? ''));
      }
      // 架构页挂载取数（useArchiGraph 挂载发起 archi_graph）：正确形态回健康图；
      // reject 形态由 archiReject 控制（错误态用例）
      if (command === 'archi_graph') {
        if (archiReject !== null) return Promise.reject(new Error(archiReject));
        return Promise.resolve({ elements: [...ARCHI_ELEMENTS], relations: [], diagnostics: [] });
      }
      if (command === 'archi_module') {
        return Promise.resolve({
          element: ARCHI_ELEMENTS[0],
          dependsOn: [],
          dependedBy: [],
          children: [],
          docs: [],
          warnings: [],
        });
      }
      return Promise.resolve(null);
    },
  );
}

